/* A fourth, explicit difficulty tier. Stable IDs preserve account progress. */
(()=>{
const add=(id,domain,grade,topic,title,question,answer,unit,hints,steps,plan,verify,trap)=>tasks.push({id,domain,grade,topic,subject:topicSubjects[`${grade}-${topic}`],topicName:curriculum[grade][topic][0],level:3,title,question,answer,unit,hints,steps,goal:'Найти ключевую идею и доказать результат',challenge:true,isNew:true,review:{plan,verify,trap}});
add('olympiad-math-vieta','math',9,9,'Прыжок Виета: за порогом 1000',
'Положительные целые x и y удовлетворяют x² + y² + 1 = 3xy. Найди наименьшее значение x + y, превосходящее 1000. Обоснуй, почему других меньших допустимых сумм за этим порогом нет. В поле ответа введи только найденную сумму.',2207,null,
['Считай уравнение квадратным относительно y. Если один корень y — целый, то второй равен 3x − y.','Упорядочь x ≤ y и докажи, что при x > 1 замена (x,y) → (3x − y,x) уменьшает больший элемент. Разбери x = 1 отдельно.'],
['Из симметрии можно считать 1 ≤ x ≤ y. Рассмотрим f(t) = t² − 3xt + x² + 1. Один его корень y, другой y′ = 3x − y; по Виету yy′ = x² + 1. Поэтому y′ — положительное целое.',
'При x > 1 имеем f(0) = x² + 1 > 0 и f(x) = 1 − x² < 0. Значит, меньший корень лежит строго между 0 и x, а больший — строго правее x. Следовательно, y′ < x < y.',
'Пара (y′,x) снова удовлетворяет тому же уравнению, но её максимальный элемент меньше. Спускаясь по положительным целым, обязательно придём к x = 1. Тогда y² − 3y + 2 = 0, откуда y = 1 или 2.',
'Спуск однозначен при x > 1, а обратный шаг для упорядоченной пары (a,b) имеет вид (b,3b − a). Поэтому все решения, с точностью до перестановки, лежат в цепочке (1,1), (1,2), (2,5), (5,13), (13,34), (34,89), (89,233), (233,610), (610,1597), … . Базовая пара (1,2) уже следует из (1,1).',
'Начиная с (1,2), новый элемент 3b − a > b, поэтому суммы строго возрастают. Последняя сумма ниже порога равна 233 + 610 = 843; следующая — 610 + 1597 = 2207.',
'Полнота цепочки доказана спуском, поэтому никакая другая пара не даёт сумму между 1000 и 2207. Ответ: 2207.'],
'Не перебирать x и y до случайной границы, а доказать полноту решений с помощью убывающего преобразования.',
'610² + 1597² + 1 = 2922510 = 3 · 610 · 1597. Предыдущая сумма 843, следующая сумма 5778 уже больше 2207.',
'Численный перебор на ограниченном квадрате не доказывает, что решение с большей координатой и меньшей суммой пропущено не было. Здесь нужна полнота цепочки.');
add('olympiad-math-incircle','math',9,5,'Точка на вписанной окружности',
'В треугольнике ABC даны AB = 14, AC = 13, BC = 15. Точка P пробегает вписанную окружность треугольника. Найди наименьшее значение PA² + PB² + PC² и докажи, что оно достигается. Все длины заданы в одной единице.',237,null,
['Замени сумму трёх квадратов расстояний одним квадратом расстояния до центра тяжести G треугольника.','Положи A = (0;0), B = (14;0). Найди C и центр вписанной окружности I; затем минимизируй PG на окружности.'],
['Выберем A = (0;0), B = (14;0), C = (u;v), v > 0. Из u² + v² = 169 и (u − 14)² + v² = 225 получаем u = 5, v = 12.',
'Площадь треугольника Δ = 14 · 12 / 2 = 84, полупериметр s = 21. Поэтому радиус вписанной окружности r = Δ/s = 4.',
'Центр вписанной окружности — взвешенное среднее вершин с весами противоположных сторон: I = (15A + 13B + 14C)/42 = (6;4). Центр тяжести G = (A + B + C)/3 = (19/3;4). Значит, IG = 1/3.',
'Для любой точки P верно PA² + PB² + PC² = 3PG² + GA² + GB² + GC². Доказательство: разложи векторы PA = PG + GA и аналогично; смешанные слагаемые сокращаются, поскольку GA + GB + GC = 0.',
'Постоянная GA² + GB² + GC² = (AB² + BC² + CA²)/3 = (196 + 225 + 169)/3 = 590/3.',
'G лежит внутри окружности. Для точки P на ней из неравенства треугольника PG ≥ IP − IG = 4 − 1/3 = 11/3. Равенство достигается на луче IG, то есть при P = (10;4).',
'Искомый минимум равен 3 · (11/3)² + 590/3 = 237. Непосредственно в точке (10;4): PA² = 116, PB² = 32, PC² = 89; их сумма 237.'],
'Выделить центр тяжести, чтобы задача о трёх расстояниях превратилась в поиск ближайшей к G точки окружности.',
'P = (10;4) принадлежит окружности: IP = 4. Прибавка 3PG² минимальна именно здесь, а 116 + 32 + 89 = 237.',
'Нельзя положить P = G: по условию P лежит на окружности, а G — внутри неё. Также нельзя подменять центр тяжести центром вписанной окружности.');
add('olympiad-physics-wedge','physics',10,11,'Скользящий клин: время спуска',
'Клин массы M = 3 кг стоит на гладком горизонтальном столе и может поступательно двигаться без вращения. Его наклонная грань образует угол 30° с горизонтом. На грани на расстоянии 2 м от нижнего края находится брусок массы m = 1 кг. Клин и брусок одновременно отпускают из покоя. Трение везде отсутствует, контакт сохраняется, g = 10 м/с². За какое время брусок достигнет нижнего края? Учитывай движение клина; ответ дай в секундах.',Math.sqrt(13/20),'с',
['Введи координату X клина и путь s бруска относительно клина. Горизонтальная скорость бруска равна Ẋ + ṡ cos α.','Используй сохранение горизонтального импульса, исключи Ẋ из кинетической энергии. Найди эффективный коэффициент при ṡ².'],
['Ось x направим по горизонтальной проекции спуска. Пусть s — путь вдоль грани относительно клина, X — горизонтальное смещение клина. Тогда vₓ бруска = Ẋ + ṡ cos α, vᵧ = −ṡ sin α.',
'Внешних горизонтальных сил нет. Начальный импульс нулевой: (M + m)Ẋ + m ṡ cos α = 0, откуда Ẋ = −m cos α · ṡ/(M + m).',
'Полная кинетическая энергия T = M Ẋ²/2 + m[(Ẋ + ṡ cos α)² + ṡ² sin² α]/2. После подстановки T = m(M + m sin² α)ṡ²/[2(M + m)].',
'Потеря потенциальной энергии равна mgs sin α. Поэтому ṡ² = 2g sin α · (M + m)/(M + m sin² α) · s. Дифференцируя при ṡ > 0 и продолжая результат к старту, получаем постоянное относительное ускорение a = g sin α · (M + m)/(M + m sin² α).',
'При α = 30°, M = 3 кг, m = 1 кг: a = 10 · (1/2) · 4/(3 + 1/4) = 80/13 м/с². Оно больше g sin α: движение опоры ускоряет относительный спуск.',
'Из s = at²/2 при s = 2 м получаем t² = 4/(80/13) = 13/20 с². Следовательно, t = √(13/20) ≈ 0,806226 с.',
'Контакт допустим: N = mMg cos α/(M + m sin² α) > 0. При M → ∞ формула ускорения переходит в a = g sin α для неподвижного клина.'],
'Связать движение опоры и бруска через горизонтальный импульс, затем использовать энергию всей системы, а не одного бруска.',
'За найденное время относительный путь a t²/2 равен 2 м. Потеря энергии mg · 2 sin 30° = 10 Дж равна кинетической энергии клина и бруска вместе.',
'Формула t = √(2s/(g sin α)) верна лишь для закреплённого клина. Нельзя применять сохранение механической энергии только к бруску: движущаяся опора совершает над ним работу.');
add('olympiad-physics-capacitor','physics',11,12,'Стержень, поле и конденсатор',
'Два неподвижных параллельных проводящих рельса лежат в горизонтальной плоскости на расстоянии l = 1 м. Скользящий без трения стержень массы m = 0,020 кг замыкает их. Неподвижные концы рельсов соединены последовательной цепью из резистора R = 5 Ом и конденсатора C = 0,010 Ф. Поле B = 2 Тл перпендикулярно плоскости рельсов и однородно на всём пути. Вначале конденсатор разряжен, скорость стержня v₀ = 10 м/с направлена вдоль рельсов от неподвижной цепи. Сопротивления рельсов и стержня и самоиндукция пренебрежимо малы, источника питания нет. Какое суммарное количество теплоты выделится в резисторе за всё время? Ответ дай в джоулях.',2/3,'Дж',
['Обозначь накопленный заряд q. Из m dv/dt = −BlI и I = dq/dt получи связь v с q, не решая уравнение по времени.','В конце ток стремится к нулю, но стержень не обязан остановиться: Blv∞ = q∞/C. Учти остаточную кинетическую энергию и энергию конденсатора.'],
['Выберем положительный ток в направлении заряда конденсатора от ЭДС движения. Тогда Blv = RI + q/C. Сила Ампера тормозит стержень: m dv/dt = −BlI, где I = dq/dt.',
'Интегрируя последнее равенство от начального состояния, получаем mv + Blq = mv₀. Это интеграл уравнений движения, а не закон сохранения механического импульса стержня: магнитное поле действует внешней силой.',
'Подстановка v = v₀ − Blq/m в уравнение цепи даёт R dq/dt + (1/C + B²l²/m)q = Blv₀. Коэффициенты положительны, поэтому q монотонно приближается к конечному q∞, а ток стремится к нулю.',
'В пределе Blv∞ = q∞/C. Совместно с mv∞ + Blq∞ = mv₀ это даёт v∞ = mv₀/(m + CB²l²), q∞ = CBlmv₀/(m + CB²l²).',
'Здесь CB²l² = 0,040 кг, поэтому v∞ = 10/3 м/с и q∞ = 1/15 Кл. Стержень продолжает двигаться равномерно: ЭДС движения компенсирована напряжением конденсатора.',
'Умножая уравнение движения на v, а уравнение цепи на I, получаем d(mv²/2 + q²/(2C))/dt = −RI². Значит, Q = mv₀²/2 − mv∞²/2 − q∞²/(2C).',
'Начальная энергия равна 1 Дж, конечная кинетическая — 1/9 Дж, энергия конденсатора — 2/9 Дж. Следовательно, Q = 1 − 1/9 − 2/9 = 2/3 Дж.',
'Сопротивление влияет на скорость процесса, но не на интегральное тепло. Постоянная времени τ = mRC/(m + CB²l²) = 1/60 с; интегрирование RI² для экспоненциального тока также даёт 2/3 Дж.'],
'Найти интеграл движения «скорость–заряд», затем конечное состояние и полный энергетический баланс без потери остаточной энергии.',
'I(t) = 4e^(−60t) А, поэтому ∫₀∞ RI² dt = 5 · 16/120 = 2/3 Дж. Размерность CB²l² совпадает с массой.',
'Нельзя считать, что вся начальная энергия превратится в тепло или что стержень обязательно остановится: конденсатор оставляет ненулевую установившуюся скорость.');
})();
